{"python_code":"def build(p, frame):
    axis = App.Vector(1, 0, 0)

    def cylinder(radius, start, end):
        return Part.makeCylinder(radius, end - start,
                                 App.Vector(start, 0, 0), axis)

    x0 = p['x0']
    shoulder = p['shoulder']
    sleeve_end = x0 + p['sleeve_length']

    bearing = cylinder(p['outer_radius'], shoulder, p['bearing_end'])
    for radius, start, end in (
        (p['rear_bore'], shoulder, p['relief_start']),
        (p['relief_radius'], p['relief_start'], p['relief_end']),
        (p['front_bore'], p['relief_end'], p['bearing_end']),
    ):
        bearing = bearing.cut(cylinder(radius, start, end))
    bearing = bearing.removeSplitter()

    sleeve = cylinder(p['sleeve_radius'], x0, sleeve_end).fuse(
        cylinder(p['outer_radius'], x0, shoulder)
    )
    void = cylinder(p['sleeve_bore'], x0, sleeve_end)
    count = int(p['groove_count'])
    if count != p['groove_count'] or count < 0:
        raise ValueError('groove_count must be a nonnegative integer')
    for i in range(count):
        groove = Part.makeBox(
            p['sleeve_length'], p['groove_root'], p['groove_width'],
            App.Vector(x0, 0, -p['groove_width'] / 2.0)
        )
        groove.rotate(App.Vector(0, 0, 0), axis, 360.0 * i / count)
        void = void.fuse(groove)
    sleeve = sleeve.cut(void.removeSplitter()).removeSplitter()

    result = {'bearing': bearing, 'sleeve': sleeve}
    for name, shape in result.items():
        if shape.isNull() or not shape.isValid() or len(shape.Solids) != 1:
            raise ValueError(name + ' must be a valid single solid')
        shape.Placement = frame.multiply(shape.Placement)
    return result
","explanation":"Builds the stepped bearing bore and overlapping flanged sleeve in local coordinates. Rectangular grooves are united with the sleeve’s circular bore before cutting. Each separate solid receives the supplied frame exactly once. Assumes dimensions describe feasible solids; execution was not tested."}
